import logging
from collections.abc import Iterable
from datetime import datetime
from typing import Any

import pandas as pd

from ..config_service import get_esuite_api_config
from ..db.db_service import execute_dataframe_query, execute_sql_query
from ..db.import_service import mark_expired_entitlement_updates_processed
from ..utils.http_utils import retry_request

logger = logging.getLogger(__name__)

PROGRESS_LOG_INTERVAL = 50


def run_add_entitlement(dry_run: bool = False) -> pd.DataFrame:
    """Verarbeitet ausstehende Entitlement-Updates aus der Arbeitsliste.

    Markiert abgelaufene Updates, lädt die noch offenen Einträge aus der
    Datenbank und legt fehlende Entitlements über die eSuite-API an. Im
    Dry-Run werden keine API-Aufrufe zum Anlegen ausgeführt.

    Args:
        dry_run: Verhindert das Anlegen von Entitlements über die eSuite-API.

    Returns:
        DataFrame mit Ausführungs-ID, Anzahl verarbeiteter, angelegter,
        übersprungener und fehlgeschlagener Updates.
    """
    execution_time = datetime.now()
    execution_id = int(execution_time.timestamp())

    mark_expired_entitlement_updates_processed()
    subscriptions_df = get_pending_entitlement_updates()
    total_to_update = len(subscriptions_df)
    successful_updates = 0
    skipped_existing_entitlements = 0
    dry_run_updates = 0

    if dry_run:
        logger.info("Dry Run aktiv: Es werden keine Entitlement-POSTs ausgefuehrt.")

    logger.info("Starte Entitlement-Subscriptions: %s Datensaetze zu verarbeiten.", total_to_update)
    for processed_records, (_index, row) in enumerate(subscriptions_df.iterrows(), start=1):
        logger.debug("Entitlement-Zeile: %s", row.to_dict())
        accid = str(row["ACCOUNTID"])
        name = str(row["NAME"])
        entitlement = str(row["IDENTIFIER"])
        vkorg = str(row["VKORG"]).strip()
        start_date = str(row["STARTDATE"])
        end_date = str(row["ENDDATE"])
        logger.debug(
            "Verarbeite Account %s, VkOrg %s, Entitlement %s, Zeitraum %s bis %s.",
            accid,
            vkorg,
            entitlement,
            start_date,
            end_date,
        )

        entitlement_identifiers = get_entitlement_identifiers_for_vkorg(vkorg)
        if not entitlement_identifiers:
            entitlement_identifiers = [entitlement]

        if get_entitlement_data_acc(accid, entitlement_identifiers):
            skipped_existing_entitlements += 1
            logger.debug(
                "Account %s besitzt bereits ein aktives Entitlement fuer VkOrg %s.",
                accid,
                vkorg,
            )
            if processed_records % PROGRESS_LOG_INTERVAL == 0 or processed_records == total_to_update:
                logger.info(
                    "Fortschritt Entitlement-Subscriptions: %s/%s Datensaetze verarbeitet.",
                    processed_records,
                    total_to_update,
                )
            continue

        entitlement_data = {"name": name, "identifier": entitlement, "startDate": start_date, "endDate": end_date}

        if dry_run:
            dry_run_updates += 1
            logger.info(
                "Dry Run: Account %s, VkOrg %s, Entitlement %s, Zeitraum %s bis %s.",
                accid,
                vkorg,
                entitlement,
                start_date,
                end_date,
            )
            if processed_records % PROGRESS_LOG_INTERVAL == 0 or processed_records == total_to_update:
                logger.info(
                    "Fortschritt Entitlement-Subscriptions: %s/%s Datensaetze verarbeitet.",
                    processed_records,
                    total_to_update,
                )
            continue

        result = add_entitlement(accid, entitlement_data)
        if result.get("success"):
            successful_updates += 1
            mark_entitlement_update_processed(accid, vkorg, entitlement, str(row["STARTDATE"]), str(row["ENDDATE"]))
            logger.info("Entitlement %s fuer Account %s erfolgreich angelegt.", entitlement, accid)
        else:
            logger.error("Entitlement %s fuer Account %s fehlgeschlagen: %s", entitlement, accid, result.get("message"))

        if processed_records % PROGRESS_LOG_INTERVAL == 0 or processed_records == total_to_update:
            logger.info(
                "Fortschritt Entitlement-Subscriptions: %s/%s Datensaetze verarbeitet.",
                processed_records,
                total_to_update,
            )

    failed_updates = total_to_update - successful_updates - skipped_existing_entitlements - dry_run_updates
    logger.info(
        "Entitlement-Run abgeschlossen: gesamt=%s, angelegt=%s, vorhanden=%s, dry_run=%s, fehlgeschlagen=%s.",
        total_to_update,
        successful_updates,
        skipped_existing_entitlements,
        dry_run_updates,
        failed_updates,
    )

    result_df = pd.DataFrame(
        [
            {
                "execution_id": execution_id,
                "execution_time": execution_time,
                "total_to_update": total_to_update,
                "successful_updates": successful_updates,
                "skipped_existing_entitlements": skipped_existing_entitlements,
                "dry_run_updates": dry_run_updates,
                "failed_updates": failed_updates,
            }
        ]
    )
    return result_df


def get_sub(query: str) -> pd.DataFrame:
    """Ruft alle Subscriptions aus der PROD-Umgebung ab und gibt sie als DataFrame zurück.

    Args:
        query (str): SQL-Query zum Abrufen der Subscriptions

    Returns:
        pd.DataFrame: DataFrame mit den abgerufenen Subscriptions.
    """
    try:
        return execute_dataframe_query(query)
    except Exception as e:
        logger.exception(f"Error fetching subscriptions: {e}")
        return pd.DataFrame()


def get_pending_entitlement_updates() -> pd.DataFrame:
    """Liest noch nicht bearbeitete Entitlement-Updates aus der Arbeitsliste."""
    query = """
    SELECT
        accountid AS ACCOUNTID,
        name AS NAME,
        identifier AS IDENTIFIER,
        vkorg AS VKORG,
        startdate AS STARTDATE,
        enddate AS ENDDATE
    FROM dbm_lesermarkt.tb_entitlement_update
    WHERE bearbeitet = 0
    ORDER BY startdate, accountid, identifier
    """
    return get_sub(query)


def mark_entitlement_update_processed(
    accountid: str,
    vkorg: str,
    identifier: str,
    startdate: str,
    enddate: str,
) -> bool:
    """Markiert einen Entitlement-Update-Eintrag als bearbeitet."""
    query = """
    UPDATE dbm_lesermarkt.tb_entitlement_update
    SET bearbeitet = 1
    WHERE accountid = %s
    AND vkorg = %s
    AND identifier = %s
    AND startdate = %s
    AND enddate = %s
    """
    params = (accountid, vkorg, identifier, startdate, enddate)
    try:
        result = execute_sql_query(query, params=params)
    except Exception as e:
        logger.exception(f"Error marking entitlement update as processed for Account {accountid}: {e}")
        return False

    return result is True


def get_entitlement_identifiers_for_vkorg(vkorg: str, art: str | None = None) -> list[str]:
    """Liest die Entitlement-Identifier fuer eine VkOrg aus der Mapping-Tabelle."""
    vkorg_value = vkorg.strip()
    if not vkorg_value:
        logger.warning("Keine VkOrg fuer den Entitlement-Vergleich uebergeben.")
        return []

    query = """
    SELECT entitlement
    FROM dbm_lesermarkt.tb_mapping_entitlement
    WHERE vkorg = %s
    """
    params: tuple[str, ...]
    if art is None or not art.strip():
        params = (vkorg_value,)
    else:
        query += " AND art = %s"
        params = (vkorg_value, art.strip())

    try:
        mapping_df = execute_dataframe_query(query, params=params)
    except Exception as e:
        logger.exception(f"Error fetching entitlement mapping for VkOrg {vkorg_value}: {e}")
        return []

    if "entitlement" not in mapping_df.columns:
        logger.error("Entitlement-Mapping fuer VkOrg %s enthaelt keine Spalte 'entitlement'.", vkorg_value)
        return []

    identifiers: set[str] = set()
    for value in mapping_df["entitlement"].dropna():
        identifier = str(value).strip()
        if identifier:
            identifiers.add(identifier)

    return sorted(identifiers)


def get_entitlement_data_acc(accid: str, entitlement_identifiers: Iterable[str]) -> bool:
    """Prueft, ob ein Account eines der erwarteten Entitlements besitzt."""
    expected_identifiers = {identifier for identifier in entitlement_identifiers if identifier}
    if not expected_identifiers:
        logger.warning("Keine Entitlement-Identifier fuer den Vergleich uebergeben.")
        return False

    api_config = get_esuite_api_config("PROD")
    url = f"{api_config.resthost}accounts/{accid}/entitlements"
    try:
        response = retry_request("GET", url, headers=api_config.headers, verify=False)
        if response is None:
            logger.error(f"Keine Antwort beim Abrufen der Entitlements für Account {accid}")
            return False
        logger.debug(f"GET {url} -> status {response.status_code}")
        response_text = response.text.strip()
        if not response_text:
            logger.debug("Keine Entitlements fuer Account %s gefunden.", accid)
            return False

        try:
            response_data = response.json()
        except ValueError:
            logger.error(
                "Ungueltige JSON-Antwort beim Abrufen der Entitlements fuer Account %s: HTTP %s, Body: %s",
                accid,
                response.status_code,
                response_text[:500],
            )
            return False

        current_identifiers = _extract_entitlement_identifiers(response_data)
        matching_identifiers = current_identifiers & expected_identifiers
        if matching_identifiers:
            logger.debug("Account %s besitzt passende Entitlements: %s", accid, sorted(matching_identifiers))
            return True

        logger.debug("Account %s besitzt keine passenden Entitlements.", accid)
        return False
    except Exception as e:
        logger.exception(f"Error fetching entitlements for Account {accid}: {e}")
        return False


def _extract_entitlement_identifiers(response_data: Any) -> set[str]:
    """Extrahiert Entitlement-Identifier aus bekannten eSuite-Antwortstrukturen."""
    identifiers: set[str] = set()

    if isinstance(response_data, list):
        for item in response_data:
            identifiers.update(_extract_entitlement_identifiers(item))
        return identifiers

    if not isinstance(response_data, dict):
        return identifiers

    identifier = response_data.get("identifier")
    if isinstance(identifier, str) and identifier:
        identifiers.add(identifier)

    for key in ("entitlements", "items", "data", "response"):
        nested_data = response_data.get(key)
        if nested_data is not None:
            identifiers.update(_extract_entitlement_identifiers(nested_data))

    return identifiers


def add_entitlement(accid: str, entitlement_data: dict[str, str]) -> dict[str, Any]:
    """Fügt ein Entitlement zu einer Subscription hinzu.

    Args:
        accid (str): Die AccountID, zu der das Entitlement hinzugefügt werden soll.
        entitlement_data (dict): Die Daten des hinzuzufügenden Entitlements.

    Returns:
        dict: Das Ergebnis der API-Anfrage.
    """

    api_config = get_esuite_api_config("PROD")
    url = f"{api_config.resthost}accounts/{accid}/entitlements"
    try:
        response = retry_request("POST", url, headers=api_config.headers, json=entitlement_data, verify=False)
        if response is None:
            logger.error(f"Keine Antwort beim Hinzufügen des Entitlements für Account {accid}")
            return {"success": False, "message": "No response from server"}
        logger.debug(f"POST {url} -> status {response.status_code}")
        response_text = response.text.strip()
        if not response_text:
            return {
                "success": True,
                "message": f"Entitlement wurde mit HTTP {response.status_code} ohne Antwortinhalt angenommen",
            }

        try:
            response_data = response.json()
        except ValueError:
            logger.error(
                "Ungueltige JSON-Antwort beim Hinzufuegen des Entitlements fuer Account %s: HTTP %s, Body: %s",
                accid,
                response.status_code,
                response_text[:500],
            )
            return {
                "success": False,
                "message": f"Invalid JSON response from server (HTTP {response.status_code})",
            }

        if isinstance(response_data, dict):
            if "success" not in response_data:
                response_data["success"] = True
            return response_data

        return {
            "success": True,
            "message": f"Entitlement wurde mit HTTP {response.status_code} angenommen",
            "response": response_data,
        }
    except Exception as e:
        logger.exception(f"Error adding entitlement for Account {accid}: {e}")
        return {"success": False, "message": str(e)}
